// Decide what to publish where. Platforms that already have a post ID are skipped, so a retry never double-posts.
const p = $input.first().json;
const wanted = p.platforms || [];

const s = {
  post_id: p.post_id,
  chat_id: p.chat_id,
  access_token: p.access_token,
  media_url: p.source_media_url || null,
  fb_caption: p.fb_caption || '',
  ig_caption: p.ig_caption || '',
  fb_page_id: p.fb_page_id,
  ig_user_id: p.ig_user_id,
  fb: { wanted: wanted.includes('facebook'), post_id: p.fb_post_id, permalink: p.fb_permalink, error: null },
  ig: { wanted: wanted.includes('instagram'), media_id: p.ig_media_id, permalink: p.ig_permalink, container_id: null, error: null },
};

if (s.fb.wanted && !s.fb.post_id) {
  if (!p.access_token) s.fb.error = 'Meta access token is missing for this client.';
  else if (!p.fb_page_id) s.fb.error = 'Facebook Page ID is not configured.';
}
if (s.ig.wanted && !s.ig.media_id) {
  if (!p.access_token) s.ig.error = 'Meta access token is missing for this client.';
  else if (!p.ig_user_id) s.ig.error = 'Instagram account ID is not configured.';
  else if (!s.media_url) s.ig.error = 'Instagram posts need a photo.';
}

s.do_fb = s.fb.wanted && !s.fb.post_id && !s.fb.error;
s.do_ig = s.ig.wanted && !s.ig.media_id && !s.ig.error;

s.fb_request = s.media_url
  ? { path: `${p.fb_page_id}/photos`, body: { url: s.media_url, caption: s.fb_caption, published: true } }
  : { path: `${p.fb_page_id}/feed`, body: { message: s.fb_caption } };

return [{ json: s }];

const s = $('Plan Publish').first().json;
const res = $input.first().json;
// /photos returns { id: photoId, post_id }, /feed returns { id: "<page>_<post>" }.
const postId = res.post_id || res.id;
return [{ json: { ...s, fb: { ...s.fb, post_id: postId, permalink: `https://www.facebook.com/${postId}` } } }];

// Pull a readable message out of an HTTP Request node error item (Graph API errors are JSON inside the text).
function metaError(item) {
  const e = item?.error ?? item ?? {};
  const raw = typeof e === 'string' ? e : [e.message, e.description].filter(Boolean).join(' ');
  const m = raw.match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  return (m ? m[1] : raw || 'Unknown error').slice(0, 500);
}
const s = $('Plan Publish').first().json;
return [{ json: { ...s, fb: { ...s.fb, error: metaError($input.first().json) } } }];

// Instagram processes the image asynchronously; publish only once the container is FINISHED.
const MAX_POLLS = 20;
const s = $('Prep IG').first().json;
const status = $input.first().json;
const polls = $runIndex + 1;

let route = 1; // 0 = ready, 1 = wait and poll again, 2 = failed
let ig_error = null;
if (status.status_code === 'FINISHED') route = 0;
else if (status.status_code === 'ERROR' || status.status_code === 'EXPIRED') {
  route = 2;
  ig_error = `Instagram could not process the image (${status.status || status.status_code}).`;
} else if (polls >= MAX_POLLS) {
  route = 2;
  ig_error = 'Instagram took too long to process the image.';
}

return [{ json: { ...s, route, ig_error } }];

const s = $('Prep IG').first().json;
const mediaId = $('IG: Publish').first().json.id;
const permalink = $input.first().json.permalink || null;
const containerId = $('IG: Create Container').first().json.id;
return [{ json: { ...s, ig: { ...s.ig, media_id: mediaId, permalink, container_id: containerId } } }];

// Pull a readable message out of an HTTP Request node error item (Graph API errors are JSON inside the text).
function metaError(item) {
  const e = item?.error ?? item ?? {};
  const raw = typeof e === 'string' ? e : [e.message, e.description].filter(Boolean).join(' ');
  const m = raw.match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  return (m ? m[1] : raw || 'Unknown error').slice(0, 500);
}
const s = $('Prep IG').first().json;
const item = $input.first().json;

let containerId = null;
try {
  containerId = $('IG: Create Container').first().json.id ?? null;
} catch (e) {
  // Container step did not run.
}

let error = item.ig_error || metaError(item);
if (/aspect ratio/i.test(error)) {
  error += ' Instagram only accepts images between 4:5 (portrait) and 1.91:1 (landscape). Crop the photo and send the brief again.';
}

return [{ json: { ...s, ig: { ...s.ig, error, container_id: containerId } } }];

// Final status + message for the client. The access token is deliberately left out from here on.
const s = $input.first().json;
const { fb, ig } = s;

const fbOk = !fb.wanted || !!fb.post_id;
const igOk = !ig.wanted || !!ig.media_id;
const anyOk = (fb.wanted && !!fb.post_id) || (ig.wanted && !!ig.media_id);
const nothingWanted = !fb.wanted && !ig.wanted;

const status = nothingWanted ? 'failed' : fbOk && igOk ? 'published' : anyOk ? 'partially_published' : 'failed';

const lines = [
  status === 'published' ? '✅ Published!' : status === 'partially_published' ? '⚠️ Partly published' : '❌ Publishing failed',
];
if (nothingWanted) lines.push('No platform was selected for this post.');
if (fb.wanted) lines.push(fb.post_id ? `📘 Facebook: ${fb.permalink}` : `📘 Facebook failed: ${fb.error || 'unknown error'}`);
if (ig.wanted) {
  lines.push(ig.media_id ? `📸 Instagram: ${ig.permalink || 'posted (link unavailable)'}` : `📸 Instagram failed: ${ig.error || 'unknown error'}`);
}
if (status !== 'published') lines.push('Fix the issue, then tap 🔁 Retry. Anything already posted will not be posted twice.');

const errors = [fb.error && `facebook: ${fb.error}`, ig.error && `instagram: ${ig.error}`].filter(Boolean).join(' | ');

return [{
  json: {
    post_id: s.post_id,
    chat_id: s.chat_id,
    status,
    fb_post_id: fb.post_id || '',
    fb_permalink: fb.permalink || '',
    ig_media_id: ig.media_id || '',
    ig_permalink: ig.permalink || '',
    ig_container_id: ig.container_id || '',
    error: status === 'published' ? '' : errors || 'No platform selected',
    text: lines.join('\n\n'),
    reply_markup: status === 'published'
      ? undefined
      : { inline_keyboard: [[{ text: '🔁 Retry', callback_data: `p:rty:${s.post_id}` }]] },
  },
}];
